// ⓪ LA LLAVE · CC#2 · relevo 15 (2026-10-08) · mismo patrón que `zero-risk/brief` y `zero-risk/pieza` (lección E67).
// Este sub-flujo GASTA (PDF, cable a la sala, brief) (modelo, Apify, imagen o video) o PUBLICA hacia afuera (redes, correo). Por eso exige la llave de despacho del motor en la cabecera
// `x-sala-dispatch-key` (la misma `SALA_DISPATCH_KEY` del entorno de n8n; no se copia a ningún otro sitio) y, si falta, se DETIENE antes de tocar nada.
// Falla CERRADO: sin la llave en el entorno, el flujo queda cerrado. Los disparos con horario (cron) y las llamadas internas entre flujos no pasan por aquí.
const w = $input.first().json || {}
const headers = w.headers && typeof w.headers === 'object' ? w.headers : {}
const esperada = String($env.SALA_DISPATCH_KEY || '').trim()
if (!esperada) {
  throw new Error('FLUJO_CERRADO · el motor no tiene la llave de despacho (SALA_DISPATCH_KEY) en su entorno · este flujo gasta o publica y queda cerrado hasta que exista · E67.')
}
const recibida = String(headers['x-sala-dispatch-key'] || '')
let ok = recibida.length === esperada.length
for (let i = 0; i < esperada.length; i++) ok = recibida.charCodeAt(i) === esperada.charCodeAt(i) && ok
if (!ok) {
  throw new Error('FLUJO_PROCEDENCIA_INVALIDA · llave de despacho ausente o incorrecta · este flujo gasta o publica y solo lo despierta la sala · E67.')
}
return $input.all()

// CICLO DEL PLAN · tramo 2 · CC1 · 01-nov · sub-flujo «Plan · segunda mitad (PDF → brief)» · nodo Code «Sobre».
// El sub-flujo entra por DOS puertas: el webhook `zero-risk/plan-aprobado` (lo despierta la puerta `plan-aprobar` con la llave de despacho; antes pasa por
// una «⓪ Llave» igual a la de planeación) o la llamada directa desde la planeación (Execute Workflow, cuando NO hay compuerta: ensayo o `sin_compuerta`).
// Deja UN solo sobre normalizado en `body`: los nodos copiados de la cola de planeación leen `$('Sobre').first().json.body` donde antes leían `$('Webhook · planeacion').first().json.body`.
const e = $input.first().json || {}
const b = e.body && typeof e.body === 'object' && !Array.isArray(e.body) ? e.body : e
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
if (typeof b.plan_id !== 'string' || !UUID.test(b.plan_id)) throw new Error('SEGUNDA_MITAD_SIN_PLAN · el sobre no trae plan_id (uuid) · se DETIENE antes de tocar nada')
if (typeof b.client_id !== 'string' || !UUID.test(b.client_id)) throw new Error('SEGUNDA_MITAD_SIN_CLIENTE · el sobre no trae client_id (uuid) · se DETIENE antes de tocar nada')
return [{ json: { body: {
  client_id: b.client_id, plan_id: b.plan_id, tenant_id: typeof b.tenant_id === 'string' && b.tenant_id ? b.tenant_id : b.client_id,
  aprobacion_id: typeof b.aprobacion_id === 'string' && UUID.test(b.aprobacion_id) ? b.aprobacion_id : null,
  client_name: typeof b.client_name === 'string' && b.client_name.trim() ? b.client_name.trim() : null,
  con_pendientes: b.con_pendientes === true, dry_run: b.dry_run === true, plan_v3: b.plan_v3 === true,
  corrida: typeof b.corrida === 'string' && b.corrida ? b.corrida : null,
  _journey_id: typeof b._journey_id === 'string' && b._journey_id ? b._journey_id : null,
  _sala_correlation_id: typeof b._sala_correlation_id === 'string' && b._sala_correlation_id ? b._sala_correlation_id : null,
  aprobado_por: typeof b.aprobado_por === 'string' ? b.aprobado_por : null,
  origen: typeof b.origen === 'string' ? b.origen : 'planeacion/directo',
} } }]

// CICLO DEL PLAN · tramo 2 · CC1 · 01-nov · sub-flujo «Plan · segunda mitad (PDF → brief)» · nodo Code «Plan vigente» (MISMO nombre que en planeación, a propósito:
// los nodos copiados —«Plan → Drive (PDF)», «¿Salió el PDF?», «BRIEF · sobre»— leen `$('Plan vigente').first().json` y `.jef_vigente` sin tocarlos).
// Va después de «Plan · pedir» (HTTP GET `…/rest/v1/client_historical_outputs?select=id,client_id,output_type,status,content_text,content,provenance_tag&id=eq.{{ $('Sobre').first().json.body.plan_id }}`
// con fullResponse + neverError). Sin fila, sin texto o de otro cliente: se DETIENE (no hay PDF ni brief de un plan que no existe).
const s = $('Sobre').first().json.body
const r = $input.first().json || {}
if (r.error && typeof r.error === 'object') throw new Error('SEGUNDA_MITAD_PLAN_NO_LEGIBLE · la lectura del plan falló antes de recibir respuesta (' + String(r.error.message || r.error.name || 'sin detalle').slice(0, 160) + ')')
if (Number(r.statusCode) !== 200) throw new Error('SEGUNDA_MITAD_PLAN_NO_LEGIBLE · la base contestó ' + String(r.statusCode))
const filas = Array.isArray(r.body) ? r.body : []
const fila = filas[0]
if (!fila || !fila.id) throw new Error('SEGUNDA_MITAD_PLAN_INEXISTENTE · no existe el plan ' + String(s.plan_id))
if (String(fila.client_id) !== String(s.client_id)) throw new Error('SEGUNDA_MITAD_PLAN_DE_OTRO_CLIENTE · el plan no es de este cliente')
if (fila.output_type !== 'campaign_plan_90d') throw new Error('SEGUNDA_MITAD_NO_ES_UN_PLAN · la fila no es un plan de 90 días (' + String(fila.output_type) + ')')
const texto = String(fila.content_text || fila.content || '').trim()
if (!texto) throw new Error('SEGUNDA_MITAD_PLAN_SIN_TEXTO · el plan no tiene texto')
return [{ json: Object.assign({}, fila, { jef_vigente: {
  texto: texto, caracteres: texto.length, con_pendientes: s.con_pendientes === true, pendientes: null, estado_del_plan: s.con_pendientes === true ? 'con_pendientes' : 'listo',
  client_id: fila.client_id, client_name: s.client_name || 'cliente', llego_la_vuelta: true, etiqueta: s.aprobacion_id ? 'aprobada' : 'directa',
} }) }]

// 🔴 UNA CORRIDA SIN PDF NO PUEDE SALIR EXITOSA (2026-09-12 · CC#3)
//
// Ahora hay TRES cosas que pueden faltar, y se dicen por separado:
//   la vuelta del redactor · el guardado del plan · el PDF
// El guardado va ANTES de Drive a propósito: si Drive falla, el plan NO se pierde
// (medido el 12-sep: un plan de 22.060 caracteres se perdió entero porque nadie
// lo había guardado · el registro de invocaciones sólo conserva 2.000).
// 04-nov · las dos lecturas se atrapan: en este flujo «¿Llegó la vuelta?» no existe y, sin `jef_vigente`, daba un error crudo
let _pv = null; try { _pv = $('Plan vigente').first().json } catch (e) { _pv = null }
let _lv = {}; try { _lv = $('¿Llegó la vuelta?').first().json } catch (e) { _lv = {} }
const v = ((_pv && _pv.jef_vigente) || _lv || {});
const texto = String(v.texto || '');
const hayPlan = texto.trim().length > 0;

let guardado = false, guardado_id = null;
try {
  const g = $('Plan vigente').first().json;
  const gb = (g && g.body) ? g.body : g;
  const fila = Array.isArray(gb) ? gb[0] : gb;
  guardado = !!(fila && fila.id);
  guardado_id = fila && fila.id || null;
} catch (x) { guardado = false; }

let rec = null;
try { const d = $('Plan → Drive (PDF)').first().json; rec = (d && d.body) ? d.body : d; } catch (x) { rec = null; }
const hayPdf = !!(rec && rec.ok === true && rec.file_id);

const problemas = [];
if (!hayPlan) problemas.push(v.motivo || 'el redactor no devolvió texto');
if (hayPlan && !guardado) problemas.push('el plan NO quedó guardado · si Drive falla se pierde');
if (!hayPdf) problemas.push(hayPlan
  ? ('Drive no devolvió un archivo (' + String((rec && rec.motivo) || 'sin motivo') + ')')
  : 'no se llamó a Drive porque no había plan que escribir');

return [{ json: {
  ok: problemas.length === 0,
  llego_la_vuelta: v.llego_la_vuelta === true,
  hay_plan: hayPlan,
  caracteres_del_plan: texto.length,
  plan_guardado: guardado,
  plan_guardado_id: guardado_id,
  hay_pdf: hayPdf,
  file_id: rec && rec.file_id || null,
  url: rec && rec.url || null,
  carpeta: rec && rec.folder_id || null,
  problemas: problemas,
  client_id: v.client_id,
  client_name: v.client_name,
} }];

// El cable de vuelta NO puede ser mudo. Si no volvio, la sala NUNCA se entera
// de que la corrida termino y su marca queda sin resolver: la ventana del doble
// pago quedaria cerrada solo en el papel.
const r = $input.first().json || {};
const volvio = r.ok === true;
let corr = null;
try { corr = $('Sobre').first().json.body._sala_correlation_id || null; } catch (e) { corr = null; }
// Falla RUIDOSA solo si la sala lo despacho: un disparo a mano no tiene a quien
// contestarle, y marcar eso en rojo seria ruido.
if (corr && !volvio) {
  throw new Error('CABLE_DE_VUELTA_MUDO · la sala NO se entero de que la corrida termino · codigo ' + String(r.code || r.error || 'sin codigo'));
}
return [{ json: {
  cierre: 'plan_terminado',
  vuelta_ok: volvio,
  vuelta_detalle: volvio ? (r.event_id || 'sin event_id') : (r.code || r.detail || r.error || 'sin respuesta de la sala'),
  despachado_por_la_sala: !!corr,
} }];

// Si la puerta no acepto el sobre, NO se calla. Mismo patron que el resto de la casa (E101):
// una nota perdida se DECLARA, no se traga. No corrige nada.
const r = $input.first().json || {};
const cuerpo = r.body || r;
const ok = !!cuerpo && (cuerpo.ok === true || cuerpo.kind === 'accepted' || cuerpo.kind === 'duplicate');
if (!ok) {
  return [{ json: { _nota_perdida: true, motivo: 'SOBRE_DEL_BRIEF_NO_ACEPTADO',
    detalle: (cuerpo && (cuerpo.detail || cuerpo.code)) || 'sin detalle',
    flujo: 'X9F0zp6LQ2xGEYVS', nodo: "BRIEF · sobre · pedir el parte a la sala (E-brief · CC#2)" } }];
}
return [{ json: { _nota_perdida: false, sobre: cuerpo.kind || 'accepted', event_id: cuerpo.event_id || null } }];

// 🔴 EL AVISO DICE QUÉ HACER · no sólo que falló.
const r = $input.first().json;
const pasos = [];
if (!r.llego_la_vuelta) {
  pasos.push('1) la vuelta NO llegó · el plan PUEDE estar escrito: mira agent_invocations por client_id y fíjate response_length');
  pasos.push('2) si response_length es grande, el texto completo NO está en la base (guarda 2.000) · búscalo en Braintrust por session_id');
  pasos.push('3) comprueba el saldo del proveedor ANTES de reintentar · y NO repagues el raspado: reusa el pedido que armó «Redactor (B4)»');
} else if (!r.plan_guardado) {
  pasos.push('1) el plan llegó (' + r.caracteres_del_plan + ' caracteres) pero NO se guardó · revisa los permisos de client_historical_outputs');
  pasos.push('2) el texto está en esta corrida de n8n · copialo de «¿Llegó la vuelta?» antes de que caduque el historial (~4 h)');
} else {
  pasos.push('1) el plan está guardado (' + String(r.plan_guardado_id).slice(0, 8) + '…) · NO hay que volver a pagar al redactor');
  pasos.push('2) lo que falló es Drive · mira la credencial de Google en n8n · caduca cada 7 días si la app OAuth no está publicada');
  pasos.push('3) reintenta sólo Drive: POST a /webhook/zero-risk/texto-a-drive con client_id, client_name, nombre y el texto guardado');
}
return [{ json: {
  texto: ':rotating_light: *Plan sin PDF* — la corrida de planeación terminó sin documento en Drive.\n' +
    '• cliente: `' + String(r.client_name || r.client_id || '?') + '`\n' +
    '• qué falló: ' + r.problemas.join(' · ') + '\n' +
    '• plan escrito: ' + (r.hay_plan ? (r.caracteres_del_plan + ' caracteres') : 'NO') +
    ' · guardado: ' + (r.plan_guardado ? 'SÍ' : 'NO') + '\n' +
    '*Qué hacer:*\n' + pasos.map((p) => '  ' + p).join('\n'),
} }];

// V9 · al TERMINAR la corrida (plan entregado, o «repetida» ya sin gasto) se cierra la fila de `plan_corridas`. Si V9 no actuó (sin `plan_v3`), no hace nada.
const sobre = ($('Sobre').first().json.body || {})
const pide = sobre.plan_v3 === true && typeof sobre.corrida === "string" && sobre.corrida.length > 0 && typeof sobre.client_id === "string" && sobre.client_id.length > 0
if (!pide) return [{ json: { aplica: false } }]
let repetida = false
try { $('Cable · ¿volvió? · repetida').first(); repetida = true } catch (e) { repetida = false }
return [{ json: { aplica: true, cuerpo: {
  accion: "cerrar", client_id: sobre.client_id, corrida: sobre.corrida,
  estado: repetida ? "fallida" : "hecha",
  motivo: repetida ? "el cliente ya tenía un plan (corrida repetida): no se gastó" : "plan entregado",
} } }]

